import{_ as a,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Zendure Manager","description":"Modes de fonctionnement et régulation de la puissance du Zendure Manager.","frontmatter":{"title":"Zendure Manager","description":"Modes de fonctionnement et régulation de la puissance du Zendure Manager."},"headers":[],"relativePath":"fr/collection/zendure-ha/manager.md","filePath":"fr/collection/zendure-ha/manager.md","lastUpdated":1793447386000}'),i={name:"fr/collection/zendure-ha/manager.md"};function l(o,e,d,s,u,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<p><a id="zendure-gestionnaire"></a><a id="orientation-actuelle"></a></p><h1 id="zendure-manager" tabindex="-1">Zendure Manager <a class="header-anchor" href="#zendure-manager" aria-label="Permalink to &quot;Zendure Manager {#zendure-manager}&quot;">​</a></h1><p>Le Zendure Manager tente, via les appareils Zendure, d&#39;ajuster la consommation domestique (mesurée par le capteur P1) en direction de <code>0 W</code>. Pour ce faire, il pilote la puissance de charge et de décharge des appareils.</p><div class="warning custom-block"><p class="custom-block-title">HEMS et programmes de l&#39;application</p><p>Si le Zendure Manager et un système HEMS (ou un programme énergétique configuré dans l&#39;application Zendure) effectuent des régulations simultanées, ils risquent d&#39;entrer en conflit. N&#39;utilisez qu&#39;une seule stratégie de régulation active.</p></div><h2 id="p1-sensor" tabindex="-1">Capteur P1 <a class="header-anchor" href="#p1-sensor" aria-label="Permalink to &quot;Capteur P1 {#p1-sensor}&quot;">​</a></h2><p>Le capteur P1 doit fournir la consommation domestique :</p><ul><li>valeur positive : le domicile consomme de l&#39;électricité provenant du réseau</li><li>valeur négative : le domicile injecte de l&#39;électricité sur le réseau</li></ul><p>Ce capteur constitue la base de la fonction « Smart Matching ».</p><h2 id="betriebsarten" tabindex="-1">Modes de fonctionnement <a class="header-anchor" href="#betriebsarten" aria-label="Permalink to &quot;Modes de fonctionnement {#betriebsarten}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Signification</th></tr></thead><tbody><tr><td><code>Aus</code></td><td>Le gestionnaire ne pilote aucun appareil</td></tr><tr><td><code>Manuelle Leistungsregelung</code></td><td>Valeur de puissance fixe via <code>Manuelle Leistung</code></td></tr><tr><td><code>Smarte Leistungsregelung</code></td><td>Tente de maintenir le capteur P1 à 0 W</td></tr><tr><td><code>Smartes nur Entladen</code></td><td>Similaire au « Smart Matching », mais sans charge</td></tr><tr><td><code>Smartes nur Laden</code></td><td>Charge uniquement, pas de décharge</td></tr><tr><td><code>Solar speichern</code></td><td>Priorise le stockage de l&#39;énergie solaire (ou provenant d&#39;un réseau isolé/off-grid) dans les batteries</td></tr></tbody></table><h2 id="manuelle-leistung" tabindex="-1">Puissance manuelle <a class="header-anchor" href="#manuelle-leistung" aria-label="Permalink to &quot;Puissance manuelle {#manuelle-leistung}&quot;">​</a></h2><p>Avec <code>Manuelle Leistungsregelung</code>, l&#39;entité <code>Manuelle Leistung</code> détermine la quantité de puissance à injecter ou à soutirer.</p><ul><li>Valeur positive : la batterie se décharge vers la maison ou le réseau.</li><li>Valeur négative : la batterie se charge (si l&#39;appareil prend en charge la charge en courant alternatif/AC).</li></ul><h2 id="smart-matching" tabindex="-1">Smart Matching <a class="header-anchor" href="#smart-matching" aria-label="Permalink to &quot;Smart Matching {#smart-matching}&quot;">​</a></h2><p>Dans le mode « Smart Matching », le gestionnaire répartit la puissance entre les appareils disponibles. Cette répartition prend en compte le groupe de fusibles (<em>Fuse Group</em>), l&#39;état de charge (SoC), le SoC minimal, la puissance maximale et l&#39;état de l&#39;appareil.</p><p>La documentation originale (Wiki) décrit une logique de répartition qui est en partie obsolète. Par conséquent, cette page doit être considérée comme une simple indication ; il est conseillé de vérifier les informations par rapport au code actuel si nécessaire.</p><p>Wiki original :</p><ul><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Function-description" target="_blank" rel="noreferrer">Description des fonctions</a></li><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Power-distribution-strategy" target="_blank" rel="noreferrer">Stratégie de répartition de la puissance</a></li></ul>',18)])])}const g=a(i,[["render",l]]);export{m as __pageData,g as default};
